const DAY_MS = 86400000;

function parseCalendarDate(value) {
  if (
    typeof value !== "string" ||
    value.length !== 10 ||
    !/^\d{4}-\d{2}-\d{2}$/.test(value)
  ) {
    throw new RangeError("Dates must be strings in YYYY-MM-DD form.");
  }

  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));

  // Unlike Date.UTC, setUTCFullYear does not reinterpret years 00–99.
  const calendar = new Date(0);
  calendar.setUTCFullYear(year, month - 1, day);

  if (
    calendar.getUTCFullYear() !== year ||
    calendar.getUTCMonth() !== month - 1 ||
    calendar.getUTCDate() !== day
  ) {
    throw new RangeError("Invalid calendar date.");
  }

  return calendar.getTime() / DAY_MS;
}

const MIN_DAY = parseCalendarDate("0000-01-01");
const MAX_DAY = parseCalendarDate("9999-12-31");

function dayOfWeek(day) {
  // Epoch day 0 was Thursday. Normalize the remainder for pre-1970 dates.
  return (((day + 4) % 7) + 7) % 7;
}

function isWeekday(day) {
  const weekday = dayOfWeek(day);
  return weekday >= 1 && weekday <= 5;
}

function buildObservedHolidays(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array of calendar dates.");
  }

  const observed = new Set();
  const weekends = [];

  // Reserve every weekday holiday before placing any weekend holiday.
  for (const holiday of holidays) {
    const day = parseCalendarDate(holiday);
    if (isWeekday(day)) {
      observed.add(day);
    } else {
      weekends.push(day);
    }
  }

  weekends.sort((a, b) => a - b);

  // Sorted weekend holidays have nondecreasing nominal Mondays, so each
  // placement can continue after the previous placement.
  let candidate = MIN_DAY;
  for (const day of weekends) {
    const monday = day + (dayOfWeek(day) === 6 ? 2 : 1);
    candidate = Math.max(candidate, monday);

    while (!isWeekday(candidate) || observed.has(candidate)) {
      candidate += 1;
    }

    observed.add(candidate);
    candidate += 1;
  }

  return observed;
}

function lowerBound(days, target) {
  let low = 0;
  let high = days.length;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (days[middle] < target) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

// Counts an inclusive interval. observedDays is sorted and contains weekdays only.
function countBusinessDaysInRange(first, last, observedDays) {
  if (first > last) {
    return 0;
  }

  const length = last - first + 1;
  let count = Math.floor(length / 7) * 5;
  const firstWeekday = dayOfWeek(first);
  const remainder = length % 7;

  for (let offset = 0; offset < remainder; offset += 1) {
    const weekday = (firstWeekday + offset) % 7;
    if (weekday >= 1 && weekday <= 5) {
      count += 1;
    }
  }

  const holidayCount =
    lowerBound(observedDays, last + 1) -
    lowerBound(observedDays, first);

  return count - holidayCount;
}

export function isBusinessDay(date, holidays = []) {
  const day = parseCalendarDate(date);
  const observed = buildObservedHolidays(holidays);
  return isWeekday(day) && !observed.has(day);
}

export function addBusinessDays(date, n, holidays = []) {
  const day = parseCalendarDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer.");
  }

  const observedDays = Array.from(buildObservedHolidays(holidays)).sort(
    (a, b) => a - b
  );

  const forward = n >= 0;
  const origin = n === 0 ? day : day + (forward ? 1 : -1);
  const required = n === 0 ? 1 : Math.abs(n);

  let low = forward ? origin : MIN_DAY;
  let high = forward ? MAX_DAY : origin;

  if (countBusinessDaysInRange(low, high, observedDays) < required) {
    throw new RangeError("Result cannot be represented as YYYY-MM-DD.");
  }

  // Search for the day that first reaches the required count in the
  // requested direction, excluding the start unless n is zero.
  if (forward) {
    while (low < high) {
      const middle = low + Math.floor((high - low) / 2);
      if (
        countBusinessDaysInRange(origin, middle, observedDays) >= required
      ) {
        high = middle;
      } else {
        low = middle + 1;
      }
    }
  } else {
    while (low < high) {
      const middle = low + Math.ceil((high - low) / 2);
      if (
        countBusinessDaysInRange(middle, origin, observedDays) >= required
      ) {
        low = middle;
      } else {
        high = middle - 1;
      }
    }
  }

  return new Date(low * DAY_MS).toISOString().slice(0, 10);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startDay = parseCalendarDate(start);
  const endDay = parseCalendarDate(end);
  const observedDays = Array.from(buildObservedHolidays(holidays)).sort(
    (a, b) => a - b
  );

  if (startDay === endDay) {
    return 0;
  }

  const count = countBusinessDaysInRange(
    Math.min(startDay, endDay) + 1,
    Math.max(startDay, endDay),
    observedDays
  );

  return startDay > endDay && count !== 0 ? -count : count;
}
